<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,reactive,ref,watch}from'vue';import{onBeforeRouteLeave,useRoute,useRouter}from'vue-router';import{api,ApiError}from'../api';import{emptyPost,type Post}from'../types';import MarkdownView from'../components/MarkdownView.vue';const route=useRoute(),router=useRouter(),form=reactive(emptyPost()),tags=ref(''),error=ref(''),fields=ref<Record<string,string>>({}),dirty=ref(false),saved=ref(false),tab=ref<'edit'|'preview'>('edit');const id=computed(()=>route.params.id),storageKey=computed(()=>`after-draft-${id.value||'new'}`);function slug(){if(!form.slug)form.slug=form.title.toLowerCase().trim().replace(/[^a-z0-9\u4e00-\u9fa5]+/g,'-').replace(/^-|-$/g,'')}watch([form,tags],()=>{if(saved.value)return;dirty.value=true;localStorage.setItem(storageKey.value,JSON.stringify({...form,tags:tags.value}))},{deep:true});function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}onBeforeRouteLeave(()=>!dirty.value||confirm('有尚未保存的修改，确定离开吗？'));onMounted(async()=>{addEventListener('beforeunload',unload);if(id.value){const all=await api<Post[]>('/admin/posts');const p=all.find(x=>x.id===Number(id.value));if(p){Object.assign(form,p);tags.value=p.tags.join(', ')}}else{const cached=localStorage.getItem(storageKey.value);if(cached&&confirm('发现未保存的草稿，是否恢复？')){const x=JSON.parse(cached);Object.assign(form,x);tags.value=x.tags||''}}setTimeout(()=>dirty.value=false)});onBeforeUnmount(()=>removeEventListener('beforeunload',unload));async function save(){error.value='';fields.value={};try{const body={...form,tags:tags.value.split(',').map(x=>x.trim()).filter(Boolean)};const p=await api<Post>(id.value?'/admin/posts/'+id.value:'/admin/posts',{method:id.value?'PUT':'POST',body:JSON.stringify(body)});saved.value=true;dirty.value=false;localStorage.removeItem(storageKey.value);router.replace('/admin/posts/'+p.id);setTimeout(()=>saved.value=false)}catch(e){if(e instanceof ApiError){error.value=e.message;fields.value=e.fields;if(e.status===401)error.value+='。正文已保存在浏览器，请重新登录。'}}}</script><template><div class="admin-title"><div><p class="eyebrow">EDITOR</p><h1>{{id?'编辑文章':'新建文章'}}</h1></div><div><RouterLink to="/admin/posts" class="button secondary">取消</RouterLink> <button @click="save">保存文章</button></div></div><p v-if="error" class="error" role="alert">{{error}}</p><form class="editor" @submit.prevent="save"><section class="panel form"><label>标题 <span>{{fields.title}}</span><input v-model="form.title" @blur="slug" required></label><label>Slug <span>{{fields.slug}}</span><input v-model="form.slug" pattern="[a-z0-9-]+" required></label><label>摘要<textarea v-model="form.summary" rows="2"></textarea></label><div class="form-row"><label>分类<select v-model="form.category"><option>技术</option><option>随笔</option></select></label><label>状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">已发布</option></select></label></div><label>标签（逗号分隔）<input v-model="tags"></label><label>封面 URL<input v-model="form.coverUrl" type="url"></label><label class="check"><input v-model="form.featured" type="checkbox">设为精选</label></section><section class="write"><div class="tabs"><button type="button" :class="{active:tab==='edit'}" @click="tab='edit'">编辑</button><button type="button" :class="{active:tab==='preview'}" @click="tab='preview'">预览</button></div><textarea v-show="tab==='edit'" v-model="form.contentMarkdown" aria-label="Markdown 正文" placeholder="# 从这里开始写作…"></textarea><div v-show="tab==='preview'" class="preview"><MarkdownView :content="form.contentMarkdown"/></div></section></form></template>
